\Needspace{24\baselineskip}
\section{What domination proves}

\Needspace{18\baselineskip}
\begin{theorem}\label{thm:relative-domination}
Let $\theta$ be a smooth real $(1,1)$-form, let $u,v\in\PSH(X,\theta)$, and let $0\leq a<1$. If
\[
 \mathbf1_{\{u<v\}}\mathrm{MA}_\theta(u)
 \leq a\,\mathbf1_{\{u<v\}}\mathrm{MA}_\theta(v),
\]
then $u\geq v$ in each of the following regimes:
\begin{enumerate}
\item $\theta$ is semipositive and big, $P_{\delta\theta}(u)\not\equiv-\infty$ for some $\delta\in(0,1)$, and $v\preceq u$;
\item $\theta,\varphi$ satisfy the assumptions of \cref{thm:als-general-measure}, $u\in\mathcal E_{\mathrm{env}}(X,\theta,\varphi)$, $v\preceq\varphi$;
\item $X$ has bounded mass, $\theta$ is big, $\varphi=P_\theta[\varphi]$ has positive lower volume, $u\in\mathcal E_{\mathrm{vol}}(X,\theta,\varphi)$, and $v\preceq\varphi$.
\end{enumerate}
\end{theorem}

The first assertion was proved in \cref{thm:singular-strict-domination}. The second is proved without a finite-mass assumption in \cref{thm:relative-extended-domination}, starting from the finite-measure argument of \cite[Theorem 3.14]{ALS26}. The third is proved in \cref{thm:big-relative-domination}, reconstructing \cite[Proposition 3.2]{XL26} without a separate global positive-volume assumption. In the first case, a potential equivalent to an ALS model meets the smaller-background condition by a constant translation of a competitor for that model.

\begin{proposition}\label{prop:relative-uniqueness}
Fix a nonzero finite positive non-pluripolar measure $\mu$. Consider either a fixed ordinary singularity type admitting a smaller-background envelope in a semipositive big background, or one of the relative classes in parts (2) and (3) of \cref{thm:relative-domination}. In each such class, two solutions of $\mathrm{MA}_\theta(w)=\mathrm{e}^{\lambda w}\mu$ with $\lambda>0$ coincide. If $u$ and $v$ solve
\[
 \mathrm{MA}_\theta(u)=c_u\mu,\qquad
 \mathrm{MA}_\theta(v)=c_v\mu,
 \qquad c_u,c_v>0,
\]
in the same specified class, then $c_u=c_v$.
\end{proposition}
\begin{proof}
For the exponential equation fix $s>0$. On $\{u<v-s\}$,
\[
 \mathrm{MA}_\theta(u)
 =\mathrm{e}^{\lambda(u-v)}\mathrm{MA}_\theta(v)
 \leq \mathrm{e}^{-\lambda s}\mathrm{MA}_\theta(v-s).
\]
Strict domination gives $u\geq v-s$. Let $s\downarrow0$ and exchange $u,v$.

For the second assertion, suppose $c_u<c_v$. For every real $A$, the global inequality
\[
 \mathrm{MA}_\theta(u)
 =\frac{c_u}{c_v}\mathrm{MA}_\theta(v+A)
\]
implies $u\geq v+A$ by strict domination. Choose a point where both potentials are finite and let $A\to+\infty$, a contradiction. Hence $c_u\geq c_v$; exchanging the two proves equality. There is no factor strictly below one when $c_u=c_v$, so this argument does not prove equality of the potentials for the constant-density equation.
\end{proof}

The corresponding uniqueness statements in the minimal ordinary type of an arbitrary smooth big background follow from \cref{cor:big-barrier-orders}. That argument uses a strict singular barrier; it does not require semipositivity or bounded mass.

\section{The zero-exponent limit and its topology}
\label{sec:zero-exponent-topology}

The uniform limit $\lambda u_\lambda\to\log c$ proved for continuous bounded potentials in \cref{chap:weak-equations} cannot be transferred unchanged to an unbounded prescribed singularity type.

\begin{proposition}\label{prop:singular-no-uniform-limit}
Suppose $\varphi$ is unbounded below and $u_\lambda\simeq\varphi$ for every $\lambda>0$. Then $\lambda u_\lambda$ cannot converge uniformly on $X$ to a finite constant as $\lambda\downarrow0$. Its distance to any finite constant is also infinite in $L^\infty(\mathrm{d}V)$ for each fixed $\lambda>0$.
\end{proposition}
\begin{proof}
Bounded equivalence preserves unboundedness below. Every nonempty strict sublevel set of the upper semicontinuous function $u_\lambda$ is open and has positive smooth volume. Thus $u_\lambda$ is essentially unbounded below, as is $\lambda u_\lambda$. The stated conclusions follow.
\end{proof}

A fixed finite non-pluripolar measure is uniformly controlled by capacity.

\begin{lemma}\label{lem:npp-uniform-capacity}
Let $\mu$ be a finite non-pluripolar Borel measure on $X$. Then
\[
 \lim_{\delta\downarrow0}\sup\{\mu(E):E\text{ Borel},\
                      \operatorname{Cap}_\omega(E)\leq\delta\}=0.
\]
Consequently, capacity convergence implies convergence in $\mu$-measure.
\end{lemma}
\begin{proof}
If the first assertion failed, there would be $\epsilon>0$ and Borel sets $E_j$ with capacity at most $2^{-j}$ and $\mu(E_j)\geq\epsilon$. Countable subadditivity of capacity gives
\[
 \operatorname{Cap}_\omega\left(\limsup_j E_j\right)=0.
\]
The limsup is therefore pluripolar and has zero $\mu$-measure. On the other hand, finiteness of $\mu$ and continuity from above applied to $\bigcup_{j\geq k}E_j$ show that the limsup has measure at least $\epsilon$, a contradiction. Apply the first assertion to the sets on which the difference of two converging potentials exceeds a fixed positive number to get the consequence.
\end{proof}

For solutions of $\mathrm{MA}_\theta(u_\lambda)=\mathrm{e}^{\lambda u_\lambda}\mu$, write
\[
 v_\lambda=u_\lambda-\sup_Xu_\lambda,\qquad
 c_\lambda=\mathrm{e}^{\lambda\sup_Xu_\lambda}.
\]
There are three separate limit questions: whether $c_\lambda$ has a finite limit, whether the measures $c_\lambda\mathrm{e}^{\lambda v_\lambda}\mu$ converge, and whether a limit of $v_\lambda$ solves the resulting equation. The next lemma passes from the first question to the second for every fixed finite non-pluripolar measure. The third requires a continuity theorem for the Monge--Amp\`ere operator. For $L^p$ densities, the measure estimate is quantitative.

\Needspace{12\baselineskip}
\begin{lemma}\label{lem:normalized-exponential-lp}\label{lem:normalized-exponential-npp}
Let $v_j\in\PSH(X,\theta)$ satisfy $\sup_Xv_j=0$, and let $\lambda_j>0$ decrease to zero. For every finite non-pluripolar measure $\mu$,
\[
 \int_X\left|\mathrm{e}^{\lambda_jv_j}-1\right|\,\mathrm{d}\mu\longrightarrow0.
\]
If $f\in L^p(\mathrm{d}V)$ for some $p>1$, then more precisely
\[
 \int_X\left|\mathrm{e}^{\lambda_jv_j}-1\right|\,|f|\,\mathrm{d}V
 \leq C_p\lambda_j\|f\|_{L^p(\mathrm{d}V)}.
\]
The constant depends on the fixed background, $p$ and $\mathrm{d}V$.
\end{lemma}
\begin{proof}
Choose a Hermitian form $\Omega\geq\theta$. By \cref{lem:global-capacity-estimates}, for every $T>1$,
\[
 \operatorname{Cap}_\Omega(\{v_j<-T\})\leq C/T
\]
uniformly in $j$. Since $v_j\leq0$, splitting at this sublevel gives
\[
 \int_X(1-\mathrm{e}^{\lambda_jv_j})\,\mathrm{d}\mu
 \leq\lambda_jT\mu(X)+\mu(\{v_j<-T\}).
\]
The preceding lemma makes the second term uniformly small when $T$ is large. For this fixed $T$, the first term tends to zero as $j\to\infty$. This proves the general assertion. The value of the exponential is zero at a pole; pole sets have zero $\mu$-measure.

For the quantitative assertion, \cref{lem:uniform-exponential}, applied in background $\Omega$, gives a uniform $L^q$ bound for $-v_j$, where $q=p/(p-1)$. H\"older's inequality and
\[
 0\leq1-\mathrm{e}^{\lambda_jv_j}\leq\lambda_j|v_j|
\]
give the claimed estimate for every $j$.
\end{proof}

Consequently, if $u_j$ solve $\mathrm{MA}_\theta(u_j)=\mathrm{e}^{\lambda_ju_j}f\,\mathrm{d}V$, put
\[
 v_j=u_j-\sup_Xu_j,\qquad c_j=\mathrm{e}^{\lambda_j\sup_Xu_j}.
\]
If $c_j\to c<+\infty$, then the right-hand sides
$c_j\mathrm{e}^{\lambda_jv_j}f\,\mathrm{d}V$ converge in total variation to $cf\,\mathrm{d}V$. This conclusion follows from the lemma alone. To conclude that an $L^1$ limit of $v_j$ solves the limiting equation still requires continuity of the Monge--Amp\`ere operator and preservation of the relative class.

Here is one precise continuity input that supplies this step in a common regime.

\begin{theorem}\label{thm:relative-dominated-continuity}
Assume the hypotheses on $\theta,\varphi$ of \cref{thm:als-general-measure}. Suppose $u_j\in\mathcal E_{\mathrm{env}}(X,\theta,\varphi)$, $u_j\to u\in\PSH(X,\theta)$ in $L^1(X)$, and
\[
 \mathrm{MA}_\theta(u_j)\leq\nu
\]
for one finite non-pluripolar measure $\nu$. Then $u\in\mathcal E_{\mathrm{env}}(X,\theta,\varphi)$, the convergence holds in capacity, and
$\mathrm{MA}_\theta(u_j)\rightharpoonup\mathrm{MA}_\theta(u)$.
\end{theorem}

This is the fixed-measure case of \cite[Lemma 4.2 and Theorem 4.1, condition (2)]{ALS26}. A complete reconstruction is given in \cref{thm:relative-fixed-measure-continuity}. Its proof first constructs a common rooftop envelope after extraction, establishes finite mass of the limiting lower roofs, and then applies domination. Mere $L^1$ convergence, even for uniformly bounded potentials, is insufficient for the Monge--Amp\`ere passage to the limit. The common dominating measure and the positive lower mass assumption are the substantive hypotheses here.

\section[Exponential approximation without bounded mass]{Closing an exponential approximation without bounded mass}
\label{sec:exponential-closedness}

The estimates in \cref{chap:damped-measures} give a passage to the limit that requires neither bounded mass nor a positive lower volume. Its hypothesis is convergence in capacity. Establishing that convergence in an existence argument remains a separate task.

\Needspace{15\baselineskip}
\begin{theorem}\label{thm:exponential-closedness}
Fix a Hermitian metric on $X$, let $\theta$ be any smooth real $(1,1)$-form, and let $\mu$ be a finite non-pluripolar measure. Suppose $f_j\geq0$, $f_j\to f$ in $L^1(\mu)$, and $\lambda_j>0$ with $\lambda_j\to\lambda>0$. Let $u_j,u\in\PSH(X,\theta)$ be nonpositive, suppose $u_j\to u$ in capacity, and assume
\[
 \mathrm{MA}^{\mathrm{ext}}_\theta(u_j)
     =\mathrm{e}^{\lambda_j u_j}f_j\,\mu.
\]
Then $\mathrm{MA}^{\mathrm{ext}}_\theta(u)$ is finite and
\[
 \mathrm{MA}^{\mathrm{ext}}_\theta(u)=\mathrm{e}^{\lambda u}f\,\mu.
\]
The measures on the left converge weakly; the right-hand sides converge in total variation.
\end{theorem}
\begin{proof}
Discard finitely many indices so that $\lambda_j\geq\lambda/2$. Their masses are at most $\|f_j\|_{L^1(\mu)}$, hence uniformly bounded. On a deep sublevel,
\[
 \mathrm{MA}^{\mathrm{ext}}_\theta(u_j)(\{u_j<-T\})
 \leq \mathrm{e}^{-\lambda T/2}\|f_j\|_{L^1(\mu)}.
\]
The tail criterion \cref{thm:undamped-tail-continuity}, in its general-background form \cref{thm:general-background-damping}, shows that the limiting Monge--Amp\`ere measure is finite and that the left-hand sides converge weakly to it.

It remains to identify this weak limit. By \cref{lem:npp-uniform-capacity}, $u_j\to u$ in $\mu$-measure. The functions $\mathrm{e}^{\lambda u_j}$ are bounded by one and converge in $\mu$-measure to $\mathrm{e}^{\lambda u}$. The change of exponent is uniform for nonpositive arguments, because the mean-value theorem gives
\[
 \sup_{t\leq0}|\mathrm{e}^{\lambda_jt}-\mathrm{e}^{\lambda t}|
 \leq |\lambda_j-\lambda|
       \sup_{s\geq0}s \mathrm{e}^{-(\lambda/2)s}\longrightarrow0.
\]
Thus $\mathrm{e}^{\lambda_j u_j}\to \mathrm{e}^{\lambda u}$ in $\mu$-measure and, by absolute continuity, in $f\mu$-measure as well. Boundedness by one and finiteness of $f\mu$ give convergence in $L^1(f\mu)$. Therefore
\[
 \begin{split}
 \int_X|\mathrm{e}^{\lambda_j u_j}f_j-\mathrm{e}^{\lambda u}f|\,\mathrm{d}\mu
 &\leq\|f_j-f\|_{L^1(\mu)}\\
 &\quad+\int_X|\mathrm{e}^{\lambda_j u_j}-\mathrm{e}^{\lambda u}|f\,\mathrm{d}\mu
 \longrightarrow0.
 \end{split}
\]
This proves total-variation convergence and identifies the equation for $u$.
\end{proof}

Normalizing constants can be absorbed into $f_j$ whenever the resulting densities converge in $L^1(\mu)$. The theorem does not assert that an arbitrary $L^1$-convergent sequence converges in capacity or stays in a prescribed envelope class.

This argument also pinpoints the difficulty as $\lambda_j\downarrow0$: the tail bound $\mathrm{e}^{-\lambda_jT}\|f_j\|_1$ no longer tends to zero uniformly in $j$ as $T\to\infty$. A zero-exponent approximation needs another source of uniform tail control, such as the integrability condition in \cref{cor:integrability-continuity}. Global bounded mass would not by itself supply that missing tail estimate.

\input{author/section_individual_exponential_equations}

\Needspace{19\baselineskip}
\section{Consequences for the singularity program}

Ordinary singularity volumes are defined by optimizing mass within a bounded-equivalence class. They are therefore invariants of that class and may be infinite; their finiteness and comparison properties retain the hypotheses of \cref{chap:envelopes}. Multiplier-ideal equivalence is coarser. The $\mathcal I$-goodness problem asks which envelope and volume identities survive under this coarser relation.

The equation proofs separate three ingredients: relative envelopes, finite damped measures and continuity of the undamped operator. The first two are available without bounded mass. The third requires estimates for the actual approximating sequence, as in \cref{thm:exponential-closedness}.

Gauduchon metrics give an invariant linear trace and the adjoint measure controlling the smooth scalar. In \cref{chap:normalization}, logarithmic variation of the density gives supporting probabilities for prescribed-type equations. Their construction does not identify them with a linearized adjoint at a singular solution; that identification requires additional regularity.

\chapter[Relative envelopes and finite measures]{Finite measures in the relative envelope class}
\label{chap:relative-finite-measures}

The relative envelope class can contain potentials of infinite Monge--Amp\`ere mass. This does not prevent it from providing the right setting for equations with finite measures. The distinction is between a condition on singularities and the additional measure control supplied by an equation. In this chapter we develop the envelope arguments that connect the two. A positive lower volume enters explicitly. The semipositive theory is developed without an upper volume bound; the final sections treat general big backgrounds under their separate volume assumptions.

Until \cref{sec:big-relative-foundations}, $X$ is connected and compact, $\theta\geq0$ is smooth and big, and $\varphi$ satisfies \eqref{eq:als-model-condition}. Fix $0<\varepsilon<1$ with $P_{\varepsilon\theta}(\varphi)$ genuine. Write
\[
 \mathcal E_\varphi=\mathcal E_{\mathrm{env}}(X,\theta,\varphi),
 \qquad \mathcal E_0=\mathcal E_{\mathrm{env}}(X,\theta,0),
 \qquad \mu_u=\mathrm{MA}^{\mathrm{ext}}_\theta(u).
\]
The notation $Q_b$ refers to the convex competitor definition in \cref{def:relative-envelope-class}; differences at common poles are never assigned artificial values. The first envelope lemmas do not require a positive lower volume.

\section{Room below the reference potential}

\begin{lemma}\label{lem:relative-stretch-closure}
If $u\in\mathcal E_\varphi$ and $u\leq\varphi$, then $Q_b(u,\varphi)\in\mathcal E_\varphi$ for every $b\geq1$. More generally, if $u,w\in\mathcal E_\varphi$ and $u\leq w$, then $Q_b(u,w)\in\mathcal E_\varphi$.
\end{lemma}
\begin{proof}
Put $u_t=Q_t(u,\varphi)$. Fix $s\geq1$ and choose $t>bs$. The defining inequality for $u_t$ shows that
\[
 \frac bt u_t+\left(1-\frac bt\right)\varphi
 \leq bu-(b-1)\varphi.
\]
The left side is $\theta$-plurisubharmonic, so it is at most $u_b$. Consequently
\[
 \frac{bs}{t}u_t+\left(1-\frac{bs}{t}\right)\varphi
 \leq s u_b-(s-1)\varphi.
\]
This supplies a competitor for every $s$. Also $u_b\leq u\leq\varphi$, which supplies the singularity-order condition. All inequalities are interpreted off the pole sets and then as inequalities between the corresponding convex combinations of canonical potentials.

For the second assertion choose a constant $C$ such that $u-C\leq\varphi$ and $w-C\leq\varphi$. Translation reduces to $u,w\leq\varphi$. The obstacle for $Q_b(u,w)$ lies above that for $Q_b(u,\varphi)$ and below $u$, because $u\leq w\leq\varphi$. Thus
\[
 Q_b(u,\varphi)\leq Q_b(u,w)\leq u\leq\varphi.
\]
Upward stability of the relative class, proved in \cref{prop:relative-elementary}, gives the conclusion. Restoring the translation does not change class membership.
\end{proof}

\begin{lemma}\label{lem:relative-difference-envelope}
If $u\in\mathcal E_\varphi$ and $u\leq\varphi$, then
\[
 w=P_\theta(u-\varphi)\in\mathcal E_0,
 \qquad w\leq0,
 \qquad w+\varphi\leq u.
\]
\end{lemma}
\begin{proof}
Since $\varphi\leq0$, the potential $u$ is a competitor for the obstacle $u-\varphi$ away from its pole set. The envelope is genuine, bounded above by zero, and satisfies the asserted sum inequality by canonical representatives. For $b\geq1$, let $h_b=Q_b(u,\varphi)$. Then
\[
 h_b\leq bu-(b-1)\varphi\leq b(u-\varphi).
\]
Semipositivity makes $b^{-1}h_b$ a $\theta$-plurisubharmonic competitor for $w$. Hence $h_b\leq bw$, supplying a competitor for $P_\theta(bw)$ for every $b$. This is exactly $w\in\mathcal E_0$.
\end{proof}

\begin{proposition}\label{prop:relative-finite-rooftops}
The rooftop of any finite collection of members of $\mathcal E_\varphi$ is genuine and belongs to $\mathcal E_\varphi$.
\end{proposition}
\begin{proof}
It suffices first to produce a genuine rooftop for two members $u,v$. Translate them so that $u,v\leq\varphi$, and let $w_u,w_v\in\mathcal E_0$ be the preceding difference envelopes. Their rooftop $z=P_\theta(w_u,w_v)$ is genuine: the potential
\[
 \tfrac12P_\theta(2w_u)+\tfrac12P_\theta(2w_v)
 \leq w_u+w_v\leq\min(w_u,w_v)
\]
is a competitor. For each $b\geq1$, the same argument with $2b$ in place of $2$ gives a $\theta$-plurisubharmonic $h_b\leq b\min(w_u,w_v)$. Therefore $b^{-1}h_b\leq z$ and $P_\theta(bz)$ is genuine. Thus $z\in\mathcal E_0$.

Set $\delta=1-\varepsilon$ and $q=P_{\varepsilon\theta}(\varphi)$. Since $P_\theta(z/\delta)$ is genuine, the potential
\[
 \delta P_\theta(z/\delta)+q
 \leq z+\varphi\leq\min(u,v)
\]
is a genuine $\theta$-plurisubharmonic competitor. This proves nonemptiness of the rooftop for any pair in the class.

To prove class membership, put $u_b=Q_b(u,\varphi)$ and $v_b=Q_b(v,\varphi)$. They belong to $\mathcal E_\varphi$ by \cref{lem:relative-stretch-closure}, so the just-proved nonemptiness gives $r_b=P_\theta(u_b,v_b)$. If $p=P_\theta(u,v)$, then
\[
 b^{-1}r_b+(1-b^{-1})\varphi\leq p.
\]
Indeed, the left side is a $\theta$-plurisubharmonic competitor below both $u$ and $v$. This is a competitor for the defining $b$-condition of $p$. Since $p\leq u\preceq\varphi$, it proves $p\in\mathcal E_\varphi$. Iterate to handle a finite collection. These arguments reconstruct \cite[Propositions 3.5--3.7]{ALS26} in the precise forms needed here.
\end{proof}

\begin{lemma}\label{lem:smaller-background-mass-lower}
If $0<a<1$ and $q=P_{a\theta}(u)$ is genuine for $u\in\PSH(X,\theta)$, then
\[
 \int_X\mu_u\geq(1-a)^n v_-(\theta).
\]
The mass on the left is also strictly positive individually, even if $v_-(\theta)=0$.
\end{lemma}
\begin{proof}
The obstacle $u-q$ is nonnegative away from the poles. The bounded-below envelope lemma makes
$p=P_{(1-a)\theta}(u-q)$ bounded. Its measure is carried by $D=\{p+q=u\}$, and $p+q\leq u$ everywhere. Positivity of mixed products and ordered contact imply
\[
 \mathrm{MA}_{(1-a)\theta}(p)
 \leq\mathbf1_D\mathrm{MA}^{\mathrm{ext}}_\theta(p+q)
 \leq\mathbf1_D\mu_u.
\]
All assertions are first restricted away from the poles. Integrating and writing $p=(1-a)\widetilde p$ proves the lower bound from the definition of $v_-(\theta)$. The bounded potential $p$ has strictly positive mass by \cref{prop:big-noncollapsing}, since $(1-a)\theta$ is big. This proves the individual assertion as well.
\end{proof}

\begin{theorem}\label{thm:relative-uniform-mass-lower}
Every $u\in\mathcal E_\varphi$ admits a genuine $P_{(\varepsilon+\delta)\theta}(u)$ whenever $0<\delta<1-\varepsilon$. Consequently
\[
 \int_X\mu_u\geq(1-\varepsilon)^n v_-(\theta),
 \qquad \int_X\mu_u>0.
\]
The first bound is uniform over the class; the second is an individual assertion. Neither asserts finiteness.
\end{theorem}
\begin{proof}
Translate $u$ below $\varphi$ and use $w\in\mathcal E_0$ from \cref{lem:relative-difference-envelope}. The potential
\[
 P_{\varepsilon\theta}(\varphi)+\delta P_\theta(w/\delta)
 \leq\varphi+w\leq u
\]
has background $(\varepsilon+\delta)\theta$. It supplies the asserted competitor. Apply \cref{lem:smaller-background-mass-lower} and let $\delta\downarrow0$ for the uniform estimate. The individual conclusion follows by taking any one such $\delta$. This is the lower-volume mechanism of \cite[Proposition 3.8]{ALS26}.
\end{proof}

\section{Domination with one finite measure}

We now impose the separate condition
\begin{equation}\label{eq:relative-positive-lower-volume}
 v_-(\theta)>0.
\end{equation}
Set $\kappa=(1-\varepsilon)^n v_-(\theta)>0$. This condition concerns a lower bound. It is compatible with $v_+(\theta)=+\infty$, as the Hopf example shows.

\begin{theorem}\label{thm:relative-finite-domination}
Let $u\in\mathcal E_\varphi$ have finite $\mu_u$, and let $v\in\PSH(X,\theta)$ satisfy $v\preceq\varphi$. If, for some $0\leq c<1$,
\[
 \mu_u\leq c\mu_v\quad\hbox{on }\{u<v\},
\]
then $u\geq v$.
\end{theorem}
\begin{proof}
Replace $v$ by $w=\max(u,v)$. Upward stability gives $w\in\mathcal E_\varphi$ and locality gives $\mu_u\leq c\mu_w$ on $\{u<w\}$. For $b>1$ put $q_b=Q_b(u,w)\in\mathcal E_\varphi$. It satisfies $q_b\leq u$, and its measure is carried by
\[
 D_b=\{b^{-1}q_b+(1-b^{-1})w=u\}.
\]
On $D_b$, positivity and ordered contact give
\[
 b^{-n}\mu_{q_b}+(1-b^{-1})^n\mu_w\leq\mu_u.
\]
Choose $b$ so large that $(1-b^{-1})^n>c$. On $D_b\cap\{u<w\}$ the preceding inequality forces both $\mu_w$ and $\mu_{q_b}$ to vanish. To justify this even when $\mu_w(X)=+\infty$, restrict first to common finite truncation levels of the potentials. On each such set the measures are finite and subtraction is legitimate. Exhausting the complements of the pole sets proves the assertion for the extended measures.

It follows that $\mu_{q_b}$ is carried by $D_b\cap\{u=w\}\subseteq\{q_b=u\}$. Since $q_b\leq u$, another application of ordered contact gives the bound with coefficient one
\begin{equation}\label{eq:relative-contact-fixed-measure}
 \mu_{q_b}\leq\mathbf1_{\{q_b=u\}}\mu_u.
\end{equation}
This coefficient is independent of $b$.

Along integers $b\to\infty$, the potentials $q_b$ decrease. If they collapsed identically to $-\infty$, compactness and Hartogs' lemma would give $M_b:=\sup_Xq_b\to-\infty$. But \eqref{eq:relative-contact-fixed-measure} would then imply
\[
 \kappa\leq\int_X\mu_{q_b}
 \leq\mu_u(\{u\leq M_b\})\longrightarrow0.
\]
Here finiteness of $\mu_u$ and its vanishing on the pole set are exactly what gives the limit. This is impossible. Hence the decreasing limit $q$ is genuine. On $\{u<w-a\}$, for any $a>0$, the defining inequality gives $q_b\leq u-(b-1)a$. Outside the poles its limit is $-\infty$ there. Such a set has smooth volume zero because $q$ is genuine. Thus $u\geq w$ almost everywhere, and then everywhere for canonical representatives. This proves the theorem.
\end{proof}

The theorem reconstructs the finite-$\mu_u$ case of \cite[Theorem 3.14]{ALS26}. Its proof displays the fixed finite measure that prevents collapse. It does not assume that every member of $\mathcal E_\varphi$ has finite mass.

\Needspace{13\baselineskip}
\begin{corollary}\label{cor:relative-finite-exponential-order}
Under the hypotheses on $u,v$ in \cref{thm:relative-finite-domination}, let $\lambda>0$. Then
\[
 \mathrm{e}^{-\lambda u}\mu_u\leq \mathrm{e}^{-\lambda v}\mu_v
 \quad\Longrightarrow\quad u\geq v.
\]
Also $\mu_u\leq c\mu_v$ on $X$ with a finite constant $c\geq0$ implies $c\geq1$.
\end{corollary}
\begin{proof}
For each $a>0$, the exponential inequality gives $\mu_u\leq \mathrm{e}^{-\lambda a}\mu_v$ on $\{u<v-a\}$. Apply the theorem to $v-a$ and then let $a\downarrow0$. The weights are finite and positive off the pole sets, so their cancellation is done there. If the second assertion failed, apply the theorem to $v+A$ for every real constant $A$, since its Monge--Amp\`ere measure is unchanged. The resulting inequalities $u\geq v+A$ contradict finiteness at a common point.
\end{proof}

In particular, two solutions in $\mathcal E_\varphi$ of an exponential equation with a fixed finite non-pluripolar right-hand measure must agree. Their Monge--Amp\`ere measures are finite because their potentials are bounded above. For the equation $\mu_u=c\nu$, the positive scalar is unique whenever two such finite-measure solutions exist. No assertion of uniqueness modulo constants for the zero-exponent potentials follows from this argument.

